pub struct E {
    v: f64,
}

impl E {
    pub fn of(v: f64) -> E {
        E { v: v }
    }
    pub fn get(self: &E) -> f64 {
        self.v
    }
    pub fn add(self: &E, other: &E) -> E {
        E { v: self.v + other.v }
    }
}

